//#region src/farcrysis-hitl.ts
/**
* farcrysis-hitl.ts — dev-only HITL overlay for the F4RCry515 arena.
*
* Mounted ONLY when the page URL carries ?hitl=1 (the caller in legacy-main.ts
* gates it). Renders spawn markers, opposing-spawn sightlines, cover
* wireframes, kill-volume checks and a status line. All setup is guarded so
* this never throws for the real game path.
*/
var COVER_HEIGHT = 1.2;
var TEAM_COLORS = {
	0: 65535,
	1: 16711935
};
function pointInBounds(x, z, b) {
	return x >= b.minX && x <= b.maxX && z >= b.minZ && z <= b.maxZ;
}
function makeTeamLabel(team, color) {
	const canvas = document.createElement("canvas");
	canvas.width = 64;
	canvas.height = 64;
	const ctx = canvas.getContext("2d");
	if (ctx) {
		ctx.clearRect(0, 0, canvas.width, canvas.height);
		ctx.font = "bold 44px monospace";
		ctx.textAlign = "center";
		ctx.textBaseline = "middle";
		ctx.fillStyle = "#ffffff";
		ctx.fillText(String(team), 32, 32);
	}
	const sprite = new Sprite(new SpriteMaterial({
		map: new CanvasTexture(canvas),
		color,
		transparent: true,
		depthTest: false,
		depthWrite: false
	}));
	sprite.scale.set(.9, .9, 1);
	return sprite;
}
function mountFarcrysisHitlOverlay(arena) {
	const added = [];
	const killVolumeViolations = [];
	let statusEl = null;
	const ensureStatus = () => {
		if (statusEl) return statusEl;
		statusEl = document.createElement("div");
		statusEl.id = "farcrysis-hitl-status";
		const s = statusEl.style;
		s.position = "fixed";
		s.top = "8px";
		s.right = "8px";
		s.zIndex = "9999";
		s.fontFamily = "monospace";
		s.fontSize = "11px";
		s.lineHeight = "1.5";
		s.color = "#e8e8e8";
		s.background = "rgba(8, 8, 14, 0.85)";
		s.border = "1px solid #555";
		s.padding = "6px 10px";
		s.borderRadius = "4px";
		s.pointerEvents = "none";
		s.whiteSpace = "pre";
		document.getElementById("farcrysis-hitl-status")?.remove();
		document.body.appendChild(statusEl);
		return statusEl;
	};
	try {
		const teamPoints = [{
			team: 0,
			points: arena.spawns[0] ?? []
		}, {
			team: 1,
			points: arena.spawns[1] ?? []
		}];
		for (const { team, points } of teamPoints) {
			const color = TEAM_COLORS[team];
			points.forEach((p, _i) => {
				const marker = new Mesh(new BoxGeometry(.4, .4, .4), new MeshBasicMaterial({ color }));
				marker.position.set(p.x, p.y + .2, p.z);
				arena.root.add(marker);
				added.push(marker);
				const label = makeTeamLabel(team, color);
				label.position.set(p.x, p.y + 1.15, p.z);
				arena.root.add(label);
				added.push(label);
			});
		}
		const s0 = arena.spawns[0] ?? [];
		const s1 = arena.spawns[1] ?? [];
		const pairCount = Math.min(s0.length, s1.length);
		for (let i = 0; i < pairCount; i++) {
			const a = s0[i];
			const b = s1[i];
			if (!a || !b) continue;
			const within = a.distanceTo(b) <= 22;
			const line = new Line(new BufferGeometry().setFromPoints([a, b]), new LineBasicMaterial({
				color: within ? 16724804 : 3407718,
				transparent: true,
				opacity: within ? .45 : .3
			}));
			arena.root.add(line);
			added.push(line);
		}
		for (const cover of arena.physicalCover) {
			const b = cover.bounds;
			const w = Math.max(b.maxX - b.minX, .01);
			const d = Math.max(b.maxZ - b.minZ, .01);
			const cx = (b.minX + b.maxX) / 2;
			const cz = (b.minZ + b.maxZ) / 2;
			const frame = new LineSegments(new EdgesGeometry(new BoxGeometry(w, COVER_HEIGHT, d)), new LineBasicMaterial({
				color: 16768256,
				transparent: true,
				opacity: .85
			}));
			frame.position.set(cx, COVER_HEIGHT / 2, cz);
			arena.root.add(frame);
			added.push(frame);
		}
		for (const { team, points } of teamPoints) points.forEach((p, i) => {
			for (const cover of arena.physicalCover) if (pointInBounds(p.x, p.z, cover.bounds)) {
				killVolumeViolations.push(`KILL-VOL: team ${team} spawn#${i} (${p.x.toFixed(1)}, ${p.z.toFixed(1)}) inside cover "${cover.id}"`);
				break;
			}
		});
		const hitl = farcrysisHITL(arena);
		const lines = [
			"[F4RCry515 HITL]",
			`spawns: ${hitl.spawnCount}   covers: ${hitl.coverCount}`,
			`maxSight: ${hitl.maxSightline}m   flow: ${String(hitl.matchFlow)}`,
			`killVol violations: ${killVolumeViolations.length}   farcrysis violations: ${hitl.violations.length}`,
			...killVolumeViolations.map((v) => `  ! ${v}`)
		];
		ensureStatus().textContent = lines.join("\n");
	} catch (err) {
		const msg = err instanceof Error ? err.message : String(err);
		console.warn("[farcrysis-hitl] setup error:", err);
		ensureStatus().textContent = `[F4RCry515 HITL] ERROR: ${msg}`;
	}
	return { dispose() {
		for (const obj of added) {
			arena.root.remove(obj);
			const disposable = obj;
			disposable.geometry?.dispose();
			if (Array.isArray(disposable.material)) for (const m of disposable.material) m.dispose();
			else disposable.material?.dispose();
		}
		added.length = 0;
		statusEl?.remove();
		statusEl = null;
	} };
}
