function formatMatchClock(milliseconds, ceil = false) {
	if (!Number.isFinite(milliseconds)) return "--:--";
	const seconds = Math.max(0, ceil ? Math.ceil(milliseconds / 1e3) : Math.floor(milliseconds / 1e3));
	return `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
}
function rulesSummary(rules) {
	if (rules.durationMs === null && rules.scoreLimit === null) return "UNTIMED SCORE PRACTICE";
	if (rules.scoreLimit === null) return "FIVE MINUTES · MOST KILLS WINS";
	return `FIRST SQUAD TO ${rules.scoreLimit}`;
}
function matchPresentationAt(state, now, scores, playerTeam, rules = DEFAULT_MATCH_RULES, arenaLabel = "Nuke Town") {
	if (state.phase === "warmup") {
		const remaining = Math.max(0, Math.ceil((state.endsAt - now) / 1e3));
		return {
			timer: formatMatchClock(state.endsAt - now, true),
			objective: `MATCH STARTS IN ${remaining}`,
			headline: remaining > 0 ? String(remaining) : "ENGAGE",
			subline: rulesSummary(rules)
		};
	}
	if (state.phase === "ended") {
		const draw = state.winner === "draw";
		const won = state.winner === playerTeam;
		return {
			timer: "00:00",
			objective: state.endReason === "score" ? "SCORE LIMIT REACHED" : "TIME LIMIT REACHED",
			headline: draw ? "DRAW" : won ? "VICTORY" : "DEFEAT",
			subline: `${scores[0]} — ${scores[1]}`
		};
	}
	const leader = scores[0] === scores[1] ? "TIED" : scores[playerTeam] > scores[playerTeam === 0 ? 1 : 0] ? "YOUR SQUAD LEADS" : "HOSTILE SQUAD LEADS";
	return {
		timer: formatMatchClock(state.endsAt - now),
		objective: `${arenaLabel.toUpperCase()} · ${rulesSummary(rules)} · ${leader}`,
		headline: null,
		subline: null
	};
}
function respawnPresentation(endsAt, now) {
	return `REDEPLOYING IN ${Math.max(0, (endsAt - now) / 1e3).toFixed(1)}s`;
}
