	const matrix = new Matrix4();
	for (let index = 0; index < flowerCount; index += 1) {
		const bed = flowerBeds[index % flowerBeds.length];
		const ring = Math.floor(index / flowerBeds.length);
		const angle = index * 2.399963229728653;
		const radius = .28 + ring % 4 * .24;
		const x = bed[0] + Math.cos(angle) * radius;
		const z = bed[1] + Math.sin(angle) * radius * .62;
		const height = .32 + index % 5 * .035;
		matrix.compose(new Vector3(x, height / 2 + .04, z), new Quaternion(), new Vector3(1, height / .42, 1));
		stems.setMatrixAt(index, matrix);
		const bloomScale = .82 + index % 4 * .09;
		matrix.compose(new Vector3(x, height + .05, z), new Quaternion().setFromEuler(new Euler(index * .17, angle, 0)), new Vector3(bloomScale, bloomScale, bloomScale));
		blooms.setMatrixAt(index, matrix);
		if (index % 3 === 1) blooms.setColorAt(index, new Color(14180204));
		else if (index % 3 === 2) blooms.setColorAt(index, new Color(7983056));
	}
	stems.instanceMatrix.needsUpdate = true;
	blooms.instanceMatrix.needsUpdate = true;
	stems.userData.dynamic = true;
	blooms.userData.dynamic = true;
	if (blooms.instanceColor) blooms.instanceColor.needsUpdate = true;
	decorative(stems);
	decorative(blooms);
	group.add(stems, blooms);
	const timber = texturedMaterial("./assets/original/textures/wood-deck.png", {
		color: 10253392,
		roughness: .9,
		repeatX: 3,
		normalPath: "./assets/original/textures/wood-deck-normal.png",
		roughnessPath: "./assets/original/textures/wood-deck-roughness.png",
		normalScale: .35
	});
