function decorative(mesh) {
	mesh.traverse((node) => {
		node.userData.blocksShots = false;
		if (node instanceof Mesh) {
			node.castShadow = false;
			node.receiveShadow = true;
		}
	});
	return mesh;
}
function createSignTexture(label) {
	const canvas = document.createElement("canvas");
	canvas.width = 768;
	canvas.height = 180;
	const context = canvas.getContext("2d");
	context.fillStyle = "#21343a";
	context.fillRect(0, 0, canvas.width, canvas.height);
	context.strokeStyle = "#e4bc4d";
	context.lineWidth = 12;
	context.strokeRect(10, 10, canvas.width - 20, canvas.height - 20);
	context.fillStyle = "#f3ead5";
	context.textAlign = "center";
	context.textBaseline = "middle";
	context.font = "700 62px system-ui, sans-serif";
	context.fillText(label, canvas.width / 2, canvas.height / 2 + 2);
	const texture = new CanvasTexture(canvas);
	texture.colorSpace = SRGBColorSpace;
	return texture;
}
