var VIEWMODEL_ARM_EVIDENCE_ATTRIBUTE = "viewmodelArmEvidenceOwnership";
var VIEWMODEL_ARM_EVIDENCE_CONTRACT = "actual-skinned-vertex-arm-only-material-id-v1";
function firstPersonArmBoneSide(name) {
	if (/^(?:UpperArm|LowerArm|Wrist|Hand|Palm|Index\d+|Middle\d+|Ring\d+|Pinky\d+|Thumb\d+)L$/u.test(name)) return "left";
	if (/^(?:UpperArm|LowerArm|Wrist|Hand|Palm|Index\d+|Middle\d+|Ring\d+|Pinky\d+|Thumb\d+)R$/u.test(name)) return "right";
	return null;
}
function createViewmodelArmEvidenceMaterial(side) {
	const material = new MeshBasicMaterial({
		color: side === "left" ? 1703754 : 16717647,
		depthTest: false,
		depthWrite: false,
		fog: false,
		side: 0,
		toneMapped: false
	});
	material.name = `qa-${side}-arm-skinned-material-id`;
	material.onBeforeCompile = (shader) => {
		shader.vertexShader = shader.vertexShader.replace("#include <common>", `#include <common>\nattribute float ${VIEWMODEL_ARM_EVIDENCE_ATTRIBUTE};\nvarying float vViewmodelArmEvidenceOwnership;`).replace("#include <begin_vertex>", `#include <begin_vertex>\nvViewmodelArmEvidenceOwnership = ${VIEWMODEL_ARM_EVIDENCE_ATTRIBUTE};`);
		shader.fragmentShader = shader.fragmentShader.replace("#include <common>", "#include <common>\nvarying float vViewmodelArmEvidenceOwnership;").replace("#include <clipping_planes_fragment>", "#include <clipping_planes_fragment>\nif (vViewmodelArmEvidenceOwnership < 0.25) discard;");
	};
	material.customProgramCacheKey = () => `${VIEWMODEL_ARM_EVIDENCE_CONTRACT}:${side}`;
	return material;
}
