		const windup = MathUtils.smoothstep(progress, 0, .14);
		const thrust = MathUtils.smoothstep(progress, .14, .44);
		const drive = thrust * (1 - MathUtils.smoothstep(progress, .58, 1));
		let right;
		let left;
		for (const rig of this.riggedArmRigs) if (rig.side === "right") right = rig;
		else left = rig;
