				this.placeRiggedShoulderEntryBelowFrame(left, cameraRotation);
				const shoulder = left.shoulder.getWorldPosition(scratch.shoulderPosition);
				const elbow = left.elbow.getWorldPosition(scratch.elbowPosition);
				const wrist = left.wrist.getWorldPosition(scratch.wristPosition);
				const upperLength = shoulder.distanceTo(elbow);
				const lowerLength = elbow.distanceTo(wrist);
				const wristTarget = arms.localToWorld(scratch.meleeWristTargetWorld.copy(MELEE_LEFT_GUARD_WRIST_TARGET_GLTF));
				const bendHint = scratch.meleeBendHintWorld.copy(MELEE_LEFT_GUARD_BEND_HINT_GLTF).applyQuaternion(armsWorldRotation).normalize();
				const handDirection = scratch.meleeHandDirectionWorld.copy(MELEE_LEFT_GUARD_HAND_DIRECTION_GLTF).applyQuaternion(armsWorldRotation).normalize();
