			const muzzle = activeModel.getObjectByName("muzzle-socket");
			const weaponForward = muzzle ? scratch.weaponForward.copy(muzzle.getWorldPosition(scratch.handTarget)).sub(socketTarget).normalize() : scratch.weaponForward.set(0, 0, 1).applyQuaternion(weaponRotation).normalize();
			const handDirection = rig.side === "left" ? riggedSupportHandDirectionLocal(reloadPose.handToReload, scratch.handDirection).applyQuaternion(weaponRotation).normalize() : scratch.handDirection.copy(weaponForward);
