		halo.name = "railgun-pickup-halo";
		halo.rotation.x = Math.PI / 2;
		halo.position.y = -.3;
		this.root.add(halo);
		this.weapon = new Group();
		this.weapon.name = "railgun-world-weapon";
		this.weapon.scale.setScalar(.58);
		this.weapon.rotation.set(.08, Math.PI / 2, -.08);
