			bloom.name = "railgun-beam-bloom";
			shock.name = "railgun-beam-shock-sheath";
			filamentRoot.name = "railgun-beam-energy-filaments";
			core.renderOrder = 18;
			bloom.renderOrder = 17;
			shock.renderOrder = 16;
