			const maximumQueueLatencyMs = Math.max(sampled.maximumQueueLatencyMs, completedPresentation.progress.maximumCompletionLatencyMs, finalQueueLatencyMs);
			assertWebGpuAdmissionCompletionLatency(`${label} adaptive admission`, maximumQueueLatencyMs, MATCH_ADMISSION_MAX_COMPLETION_LATENCY_MS);
			const nextPixelRatio = adaptiveQuality.calibrateSevereAdmissionDownshift(sampled.samples, `${label} admitted WebGPU submission window`, MATCH_ADMISSION_SEVERE_P50_MS, MATCH_ADMISSION_SEVERE_P95_MS, MATCH_ADMISSION_ADAPTIVE_MINIMUM_SAMPLES);
