function drawUsFlagLogo() {
	if (typeof document === "undefined") return null;
	const canvas = document.createElement("canvas");
	canvas.width = 640;
	canvas.height = 384;
	const context = canvas.getContext("2d");
	if (!context) return null;
	const stripeHeight = 384 / 13;
	for (let stripe = 0; stripe < 13; stripe += 1) {
		context.fillStyle = stripe % 2 === 0 ? "#b22234" : "#ffffff";
		context.fillRect(0, stripe * stripeHeight, 640, stripeHeight);
	}
	context.fillStyle = "#3c3b6e";
	context.fillRect(0, 0, 256, 7 * stripeHeight);
	const starRadius = 6.4;
	const star = (cx, cy, radius) => {
		context.beginPath();
		for (let point = 0; point < 10; point += 1) {
			const angle = -Math.PI / 2 + point * Math.PI / 5;
			const r = point % 2 === 0 ? radius : radius * .44;
			const x = cx + Math.cos(angle) * r;
			const y = cy + Math.sin(angle) * r;
			if (point === 0) context.moveTo(x, y);
			else context.lineTo(x, y);
		}
		context.closePath();
	};
	context.fillStyle = "#ffffff";
	for (let row = 0; row < 9; row += 1) {
		const count = row % 2 === 0 ? 6 : 5;
		const starRowY = stripeHeight * (row + 1) - starRadius * .8;
		for (let column = 0; column < count; column += 1) {
			star(256 / (count + 1) * (column + 1), starRowY, starRadius);
			context.fill();
		}
	}
	return canvas;
}
