			const firstPersonCatalog = menuWeaponAsset.then(() => renderRuntime.backend === "webgpu" ? runPhase("first-person-catalog", () => weaponView.prepareBrowserWeaponCatalogAssets(WEAPON_IDS, void 0, checkpoint)) : void 0);
